export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

function isLetter(cp) {
  return cp !== undefined && /[A-Za-z]/.test(cp)
}

function isDigit(cp) {
  return cp !== undefined && cp >= '0' && cp <= '9'
}

function isHexDigit(cp) {
  return cp !== undefined && /[0-9A-Fa-f]/.test(cp)
}

function isBinDigit(cp) {
